"""FSEQ v2 for Falcon Player: the header laid out as FPP reads it (byte by byte), the media file and the producer
in its variable headers, the channel data on a 4-byte boundary, and frames written and read back."""
# AI: below section was generated by an AI
import os
import struct
import sys
import tempfile

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np

from native import render_fseq as rf

fails = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        fails.append(what)


tmp = tempfile.mkdtemp()
path = os.path.join(tmp, "show.fseq")
rng = np.random.default_rng(3)
frames = rng.integers(0, 256, (30, 3 * 150), dtype=np.uint8)            # 30 frames of 150 LEDs
with open(path, "wb") as f:
    off = rf.write_header(f, 450, 30, 25, media="show.mp3", uid=12345)
    for fr in frames:
        f.write(fr.tobytes())
b = open(path, "rb").read()
check(b[:4] == b"PSEQ", "magic")
check(struct.unpack("<H", b[4:6])[0] == off and off % 4 == 0, f"channel data offset {off}, on 4 bytes")
check(b[6] == 0 and b[7] == 2, "version 2.0")
check(struct.unpack("<H", b[8:10])[0] == 32, "variable headers after the 32-byte header")
check(struct.unpack("<I", b[10:14])[0] == 450 and struct.unpack("<I", b[14:18])[0] == 30, "channels and frames")
check(b[18] == 25 and b[20] == 0 and b[21] == 0 and b[22] == 0, "25 ms a frame, uncompressed, no blocks, not sparse")
check(struct.unpack("<Q", b[24:32])[0] == 12345, "the unique id")
check(len(b) == off + 450 * 30, "the file's length: the header and every frame")
head, data = rf.read(path)
check(head["vars"].get("mf") == "show.mp3" and head["vars"].get("sp") == rf.PRODUCER, f"media and producer {head['vars']}")
check(data.shape == (30, 450) and np.array_equal(data, frames), "frames read back as written")
with open(path, "wb") as f:
    off = rf.write_header(f, 6, 2, 50)
    f.write(bytes(12))
head, data = rf.read(path)
check("mf" not in head["vars"] and data.shape == (2, 6), "no media: no mf header")

print("FAILED:", fails if fails else "none")
sys.exit(1 if fails else 0)
# AI: end
